import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const half* A, const half* B, half* C, int M, int N, int K) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += __half2float(A[row * K + k]) * __half2float(B[k * N + col]);
        }
        C[row * N + col] = __float2half(sum);
    }
}

void launch_matmul_kernel(const half* A, const half* B, half* C, int M, int N, int K) {
    dim3 blockSize(16, 16);
    dim3 gridSize((N + blockSize.x - 1) / blockSize.x, (M + blockSize.y - 1) / blockSize.y);
    matmul_kernel<<<gridSize, blockSize>>>(A, B, C, M, N, K);
}
"""

# Python wrapper
def compile_and_run():
    # Load the CUDA extension
    module = load_inline(
        name="matmul_ext",
        cpp_sources="",
        cuda_sources=cuda_source,
        functions=["launch_matmul_kernel"],
        verbose=True
    )

    class ModelNew(torch.nn.Module):
        def __init__(self):
            super(ModelNew, self).__init__()

        def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
            # Ensure inputs are fp16
            A = A.to(torch.float16)
            B = B.to(torch.float16)

            # Create output tensor
            M, K = A.shape
            K_, N = B.shape
            assert K == K_, "Matrix dimensions incompatible for multiplication"

            C = torch.empty(M, N, dtype=torch.float16, device=A.device)

            # Launch kernel
            if A.is_cuda:
                module.launch_matmul_kernel(
                    A.data_ptr(),
                    B.data_ptr(),
                    C.data_ptr(),
                    M,
                    N,
                    K
                )
            else:
                raise NotImplementedError("Only CUDA tensors are supported")

            return C

    return ModelNew

